"""Seventy explicitly authored current-course Chemistry Structure questions.
Original SVG is generated from the data and molecular frameworks in each task.
This script writes only its additions file and author-review ledger.
"""
from pathlib import Path
import json, math, re, html, hashlib, collections, xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[2]
Q=[];AUD=[];COUNTS=collections.Counter()
N=6.02e23;H=6.63e-34;C=3.00e8;R=8.31
SUB={'S1.1':'Introduction to the particulate nature of matter','S1.2':'The nuclear atom','S1.3':'Electron configurations','S1.4':'Counting particles by mass: The mole','S1.5':'Ideal gases','S2.1':'The ionic model','S2.2':'The covalent model','S2.3':'The metallic model','S2.4':'From models to materials'}
def esc(x):return html.escape(str(x))
def txt(x,y,t,size=16,anchor='middle'):
    return f'<text x="{x:.2f}" y="{y:.2f}" font-family="Arial,sans-serif" font-size="{size}" text-anchor="{anchor}" fill="black">{esc(t)}</text>'
def line(x,y,u,v,dash=False,width=1.8):
    return f'<line x1="{x:.2f}" y1="{y:.2f}" x2="{u:.2f}" y2="{v:.2f}" stroke="black" stroke-width="{width}"'+(' stroke-dasharray="5 4"' if dash else '')+'/>'
def circle(x,y,r=5,fill='white'):
    return f'<circle cx="{x:.2f}" cy="{y:.2f}" r="{r:.2f}" stroke="black" stroke-width="1.5" fill="{fill}"/>'
def svg(body,title):
    return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 430" role="img" aria-label="'+esc(title)+'"><rect width="720" height="430" fill="white"/>'+txt(360,27,title,19)+body+'</svg>'
def poly(ps,dash=False):
    return '<polyline points="'+' '.join(f'{x:.2f},{y:.2f}' for x,y in ps)+'" fill="none" stroke="black" stroke-width="2"'+(' stroke-dasharray="5 4"' if dash else '')+'/>'
def graph(title,series,xrange,yrange,xlabel='x',ylabel='y',xticks=None,yticks=None,log=False,points=False):
    x0,x1=xrange;y0,y1=yrange;f=math.log10 if log else lambda x:x
    X=lambda x:110+520*(x-x0)/(x1-x0);Y=lambda y:345-265*(f(y)-f(y0))/(f(y1)-f(y0))
    b=line(110,345,645,345)+line(110,345,110,65)+txt(620,405,xlabel,15,'end')
    b+=f'<text x="23" y="205" transform="rotate(-90 23 205)" text-anchor="middle" font-family="Arial,sans-serif" font-size="15">{esc(ylabel)}</text>'
    for x in xticks if xticks is not None else [x0,(x0+x1)/2,x1]:
        b+=line(X(x),345,X(x),351)+txt(X(x),372,x,13)
    for y in yticks if yticks is not None else [y0,(y0+y1)/2,y1]:
        b+=line(104,Y(y),110,Y(y))+txt(98,Y(y)+5,f'{y:g}',13,'end')
    for data,label in series:
        b+=poly([(X(x),Y(y)) for x,y in data])
        if points:
            for x,y in data:b+=circle(X(x),Y(y),3,'black')
        if label:b+=txt(X(data[-1][0])-5,Y(data[-1][1])-12,label,14,'end')
    return svg(b,title)
def spectrum(title,masses,intensities,labels=None):
    lo=min(masses)-1;hi=max(masses)+1;mx=max(intensities)*1.2
    X=lambda x:110+520*(x-lo)/(hi-lo);Y=lambda y:345-260*y/mx
    b=line(110,345,645,345)+line(110,345,110,65)+txt(630,404,'m/z',16,'end')
    b+=f'<text x="25" y="205" transform="rotate(-90 25 205)" text-anchor="middle" font-family="Arial,sans-serif" font-size="15">Relative intensity</text>'
    for i,(m,v) in enumerate(zip(masses,intensities)):
        tick_y=394 if i%2 and m-masses[i-1]<0.75 else 372
        b+=line(X(m),345,X(m),Y(v),width=3)+txt(X(m),tick_y,m,14)+txt(X(m),Y(v)-12,labels[i] if labels else f'{v:g}',14)
    return svg(b,title)
def orbitals(title,rows):
    b=''
    for j,(name,boxes) in enumerate(rows):
        yy=85+j*85;b+=txt(90,yy+30,name,18,'end')
        for k,occupancy in enumerate(boxes):
            xx=135+85*k;b+=f'<rect x="{xx}" y="{yy}" width="65" height="50" fill="none" stroke="black" stroke-width="1.6"/>'
            b+=txt(xx+32.5,yy+35,occupancy,23)
    return svg(b,title)
def molecule(title,atoms,bonds,lps=None,notes=()):
    # Coordinates are explicit schematic nuclear positions; multiple bonds are parallel.
    b=''
    for i,j,order in bonds:
        x,y,s=atoms[i];u,v,t=atoms[j];dx=u-x;dy=v-y;d=math.hypot(dx,dy);ux=dx/d;uy=dy/d;nx=-uy;ny=ux
        for k in range(order):
            off=(k-(order-1)/2)*7
            b+=line(x+ux*23+nx*off,y+uy*23+ny*off,u-ux*23+nx*off,v-uy*23+ny*off)
    for i,(x,y,s) in enumerate(atoms):
        b+=txt(x,y+7,s,22)
        for angle in (lps or {}).get(i,[]):
            a=math.radians(angle);px=x+30*math.cos(a);py=y-30*math.sin(a)
            b+=circle(px-3*math.sin(a),py-3*math.cos(a),1.7,'black')+circle(px+3*math.sin(a),py+3*math.cos(a),1.7,'black')
    for j,n in enumerate(notes):b+=txt(360,365+j*24,n,15)
    return svg(b,title)
def framework(title,species):
    # Several proposed electron/bond frameworks, without silently supplying requested LPs.
    b=''
    for j,(label,atoms,bonds) in enumerate(species):
        ox=(70+j*330) if len(species)==2 else ((270 if len(species)==1 else 50)+j*220);oy=140
        for a,c,order in bonds:
            x,y,s=atoms[a];u,v,t=atoms[c];dx=u-x;dy=v-y;d=math.hypot(dx,dy);nx=-dy/d;ny=dx/d
            # Keep bonds outside the full condensed-group label, including subscripts.
            trim_s=math.hypot(max(18,len(s)*21*.65/2+5)*dx/d,18*dy/d)
            trim_t=math.hypot(max(18,len(t)*21*.65/2+5)*dx/d,18*dy/d)
            for k in range(order):b+=line(ox+x+dx/d*trim_s+nx*(k-(order-1)/2)*5,oy+y+dy/d*trim_s+ny*(k-(order-1)/2)*5,ox+u-dx/d*trim_t+nx*(k-(order-1)/2)*5,oy+v-dy/d*trim_t+ny*(k-(order-1)/2)*5)
        for x,y,s in atoms:b+=txt(ox+x,oy+y+6,s,21)
        b+=txt(ox+90,310,label,17)
    return svg(b,title)
def particles(title,groups,legend='Filled circles X; open circles Y. Lines join atoms within a particle.'):
    b=''
    for i,(kind,x,y) in enumerate(groups):
        if kind=='X2':b+=line(x-11,y,x+11,y)+circle(x-11,y,8,'black')+circle(x+11,y,8,'black')
        elif kind=='Y2':b+=line(x-11,y,x+11,y)+circle(x-11,y,8)+circle(x+11,y,8)
        elif kind=='XY2':b+=line(x,y,x-17,y+15)+line(x,y,x+17,y+15)+circle(x,y,9,'black')+circle(x-17,y+15,8)+circle(x+17,y+15,8)
        else:b+=circle(x,y,9,'black' if kind=='X' else 'white')
    b+='<rect x="65" y="55" width="590" height="275" fill="none" stroke="black" stroke-width="1.5"/>'+txt(360,380,legend,14)
    return svg(b,title)
def levels(title,energies,arrows=()):
    b=''
    lo=min(energies.values());hi=max(energies.values());Y=lambda e:330-240*(e-lo)/(hi-lo or 1)
    for label,e in energies.items():b+=line(175,Y(e),550,Y(e))+txt(145,Y(e)+5,label,16,'end')
    for j,(a,c,label) in enumerate(arrows):
        x=245+75*j;y=Y(energies[a]);z=Y(energies[c])
        b+=line(x,y,x,z)+line(x,z,x-5,z+(8 if z<y else -8))+line(x,z,x+5,z+(8 if z<y else -8))+txt(x+11,(y+z)/2,label,16,'start')
    return svg(b,title)
def lattice(title,metal=False,alloy=False,shear=False):
    b=''
    for row in range(4):
        for col in range(7):
            x=135+65*col+(65 if shear and row>=2 else 0);y=105+62*row
            alt=(row+col)%2
            r=24 if not(alloy and row==1 and col in [2,5]) else 34
            b+=circle(x,y,r,'#eeeeee' if metal else ('white' if alt else '#dddddd'))+txt(x,y+6,'+' if metal or not alt else '−',20)
    if metal:
        for row in range(3):
            for col in range(6):b+=circle(165+65*col,136+62*row,2.3,'black')
    b+=txt(360,392,'Schematic slice; not a complete three-dimensional unit cell.',14)
    return svg(b,title)
def apparatus(title,mode='gas',labels=()):
    if mode=='gas':
        b=line(145,105,525,105)+line(145,280,525,280)+line(145,105,145,280)+line(525,85,525,300,width=4)+line(525,193,625,193,width=4)
        for x,y in [(200,150),(260,230),(330,145),(400,220),(465,165),(210,250)]:b+=circle(x,y,8)
    elif mode=='balance':
        b=line(140,275,580,275)+poly([(240,275),(260,165),(460,165),(480,275)])+line(270,145,450,145)+line(270,140,270,150)+line(450,140,450,150)
        b+=poly([(300,330),(360,280),(420,330),(300,330)])
    elif mode=='dilution':
        b=''
        for x in [150,365,580]:
            b+=poly([(x-18,80),(x-18,180),(x-60,300),(x+60,300),(x+18,180),(x+18,80),(x-18,80)])+line(x-18,145,x+18,145)+line(x-25,145,x+25,145)
        b+=line(225,210,290,210)+line(440,210,505,210)
    else:
        b=line(100,230,620,230)
        for x in [170,360,550]:b+=f'<rect x="{x-40}" y="125" width="80" height="150" fill="none" stroke="black" stroke-width="1.8"/>'+line(x+40,200,x+140,200)
    for j,label in enumerate(labels):b+=txt(360,350+j*24,label,15)
    return svg(b,title)
def P(prompt,*steps):return prompt,steps
def M(s):return 'M1',s
def A(s):return 'A1',s
def E(s):return 'R1',s
def near(a,b,tol=1e-7):return math.isclose(a,b,rel_tol=tol,abs_tol=1e-30)
def add(theme,title,code,stem,parts,diagram,checks,chemistry,answer=None):
    COUNTS[theme]+=1;n=700+COUNTS[theme];level='sl' if n<=714 else 'ahl';qid=f'ib-chem-{theme}-{n}'
    tested=[]
    for label,actual,expected in checks:
        assert (actual==expected if isinstance(expected,(bool,int,str)) else near(actual,expected)),(qid,label,actual,expected)
        tested.append({'check':label,'actual':actual,'expected':expected,'passed':True})
    assert tested
    ps=[];ms=[]
    for j,(prompt,steps) in enumerate(parts):
        lab=chr(97+j);marks=sum(int(c[1:]) for c,_ in steps)
        ps.append({'label':lab,'prompt':prompt,'marks':marks});ms.append({'part':lab,'steps':[{'code':c,'text':t} for c,t in steps]})
    q={'id':qid,'number':n,'source':{'document':'Independent syllabus-authored practice','question':n},'subject':'chemistry','topicId':'structure-'+theme[1],'collectionId':'chemistry-structure-'+theme[1],'subtopic':SUB[code],'syllabusCode':code,'level':level,'difficulty':'hard','calculator':True,'questionType':'data-based' if ('spectrum' in title.lower() or 'data' in title.lower() or 'curve' in title.lower()) else 'structured','title':title,'stem':stem,'parts':ps,'markScheme':ms,'marks':sum(p['marks'] for p in ps),'diagramSvg':diagram,'diagramCaption':'Original diagram. Use stated data; molecular and particle drawings are schematic.','answerSummary':answer or ' '.join(t for _,steps in parts for c,t in steps if c=='A1'),'status':'published','verification':{'method':'Author chemical reasoning review with executable numerical/electron/particle consistency checks; separate review required before release','notes':chemistry}}
    ET.fromstring(diagram);assert 8<=q['marks']<=14,(qid,q['marks'])
    Q.append(q);AUD.append({'id':qid,'level':level,'syllabusCode':code,'originalStructure':title,'chemicalReview':chemistry,'checks':tested,'marks':q['marks'],'diagramReview':'Generated as self-contained SVG from the supplied data/framework; no requested derived answers intentionally labelled.','status':'author-checked'})

