def domain_sites(title,six=False):
    center=(360,200)
    pts=[(360,75),(360,325),(520,200),(250,130),(250,270)] if not six else [(360,75),(360,325),(230,200),(490,200),(280,275),(440,125)]
    b=txt(*center,'central atom',17)
    for i,(x,y) in enumerate(pts):
        b+=line(center[0],center[1],x,y,dash=(six and i==5))+circle(x,y,19)+txt(x,y+5,i+1,16)
    b+=txt(360,382,'Six sites:opposite pairs1/2,3/4,5/6.' if six else 'Five sites:1/2 axial;3/4/5 equatorial.',15)
    b+=txt(360,408,'Schematic perspective; place bonds and lone pairs using electron accounting.',14)
    return svg(b,title)

