def polish(s):
    """Space prose/variable joins while preserving element symbols and formulas."""
    words='and or for from to of in at with than between above below by as only each through before after per around into onto inside its these this those first second third total reported corrected initial final neutral ground singly doubly molar atomic central terminal pure gaseous solid molten remaining period group model sample amount formula mean intensity electron energy step number index using isotope charge valence Use Assume Compare Find Identify For An A The'
    terms='|'.join(sorted(words.split(),key=len,reverse=True))
    s=re.sub(r'\b('+terms+r')(?=[A-Z0-9])',r'\1 ',s)
    s=re.sub(r'\bIE(?=\d)',r'IE ',s)
    s=re.sub(r',(?=\S)',', ',s)
    s=re.sub(r';(?=\S)','; ',s)
    s=re.sub(r':(?=\S)',': ',s)
    s=re.sub(r'(?<=[.!?])(?=[A-Z])',' ',s)
    s=re.sub(r'(?<=\))(?=[A-Za-z])',' ',s)
    s=re.sub(r'(?<=\d)(?=(?:mol|nm|cm|pm|kPa|Hz|kJ|J|g|K)\b)',' ',s)
    s=re.sub(r'(?<=[⁺⁻₀₁₂₃₄₅₆₇₈₉])(?=\d)',' ',s)
    s=re.sub(r'\b([HCONPSF]|Cl)([14567])\b',r'\1=\2',s)
    s=re.sub(r'\b(Na|Mg|Al|Si|P|S|Cl|Ar|Li|K|Cr|Mn)(?=\d+(?:\.\d+)?)',r'\1 ',s)
    s=s.replace('end atn=', 'end at n=').replace('isK=', 'is K=').replace('isN=', 'is N=')
    s=s.replace('0.01000Nₐ','0.01000 Nₐ').replace('0.0700Nₐ','0.0700 Nₐ')
    return s

